
const conversations=[
{icon:'▤',title:'Preparar una clase',sub:'Apoyo pedagógico',lead:'Quieres que tu clase sea más participativa.',question:'¿Qué te está costando más de tu próxima clase?',options:[{label:'Enseñar fracciones de forma entretenida',user:'Hola, Profe Gabi. Tengo que enseñar fracciones en quinto básico y quiero que mis estudiantes participen más. ¿Qué me sugieres?',gabi:'¡Hola! Podemos partir con algo concreto: representar fracciones con tiras de papel o dibujos. Luego cada grupo explica cómo obtuvo su respuesta. ¿Qué te gustaría priorizar?',follow:[{label:'Una actividad rápida para comenzar',user:'Me serviría una actividad corta para iniciar la clase.',gabi:'Podrías repartir papeles y pedir que formen un medio, un tercio y un cuarto. Comparen los resultados en parejas antes de compartirlos con el curso.',take:'Una orientación útil parte de contar el curso, el contenido y lo que quieres lograr.'},{label:'Una forma de revisar si aprendieron',user:'Quiero saber cómo comprobar que entendieron las fracciones.',gabi:'Al cerrar, muestra dos figuras y pide que expliquen cuál representa la fracción indicada y por qué. Sus explicaciones te ayudarán a identificar dudas.',take:'La IA puede sugerir estrategias, pero el docente interpreta las respuestas de sus estudiantes.'}]},{label:'Hacer participar a quienes hablan poco',user:'Hola, Profe Gabi. En mi clase algunos estudiantes casi no participan. ¿Cómo puedo darles más oportunidades?',gabi:'Puedes probar primero respuestas por escrito y luego conversaciones en parejas, antes de pedir intervenciones frente a todo el grupo. ¿Qué prefieres explorar?',follow:[{label:'Trabajo en parejas',user:'Me gustaría intentar una actividad en parejas.',gabi:'Propón una pregunta breve, deja un minuto para pensar y luego dos minutos para comentar en pareja. Después invita a compartir ideas sin obligar a nadie a exponer.',take:'Las estrategias sugeridas siempre deben adaptarse al grupo y sus necesidades.'},{label:'Participación sin hablar en público',user:'¿Hay maneras de participar sin que todos tengan que hablar frente al curso?',gabi:'Sí. Puedes usar notas anónimas, tarjetas de colores o respuestas individuales que se comentan de forma colectiva.',take:'La orientación de Profe Gabi complementa el criterio y la observación del docente.'}]},{label:'Planear mejor una evaluación',user:'Hola, Profe Gabi. Quiero preparar una evaluación sencilla para saber qué aprendió mi curso.',gabi:'Podrías comenzar por definir qué aprendizaje necesitas observar. Después elige una evidencia corta, como una explicación, un ejemplo o un ejercicio. ¿Qué te ayudaría más?',follow:[{label:'Una pregunta de cierre',user:'Necesito una pregunta para cerrar la clase.',gabi:'Prueba: “¿Qué aprendiste hoy y qué ejemplo usarías para explicárselo a otra persona?”. Ajusta la pregunta al objetivo de tu clase.',take:'La herramienta orienta la planificación; no sustituye las decisiones de evaluación del docente.'},{label:'Evaluar sin usar una prueba larga',user:'Prefiero evaluar sin hacer una prueba extensa.',gabi:'Puedes usar un ticket de salida de dos preguntas o pedir una explicación breve. Revisa las respuestas y decide qué retomar la próxima clase.',take:'El objetivo es apoyar decisiones pedagógicas concretas y posibles de aplicar.'}]}]},
{icon:'♧',title:'Gestionar mi curso',sub:'Convivencia y clima de aula',lead:'Tu grupo conversa mucho y cuesta mantener la atención.',question:'¿Qué situación te gustaría abordar?',options:[{label:'Hay mucho ruido y se distraen',user:'Hola, Profe Gabi. Mi séptimo básico conversa mucho y pierdo tiempo intentando recuperar la atención.',gabi:'Entiendo. Podrías establecer una señal clara para iniciar, proponer tareas cortas y acordar las reglas de participación con el grupo. ¿Con qué te gustaría comenzar?',follow:[{label:'Crear acuerdos de convivencia',user:'Quiero construir acuerdos con el curso.',gabi:'Invítalos a proponer dos o tres acciones que ayuden a escuchar y participar. Escríbanlas en un lugar visible y revísenlas juntos periódicamente.',take:'La IA sugiere alternativas para trabajar el clima de aula; el docente decide y acompaña.'},{label:'Recuperar la atención sin gritar',user:'¿Cómo puedo recuperar la atención de forma respetuosa?',gabi:'Prueba una señal breve y consistente, espera unos segundos y retoma con una consigna concreta. Observa qué funciona mejor en tu contexto.',take:'El acompañamiento puede ayudar a pensar opciones prácticas, no imponer decisiones.'}]},{label:'Quiero mejorar el trabajo en equipo',user:'Hola, Profe Gabi. Cuando mis estudiantes trabajan en equipo, algunos hacen todo y otros se quedan sin participar.',gabi:'Podrías asignar roles rotativos y un objetivo muy concreto a cada equipo. ¿Quieres empezar por los roles o por la evaluación del trabajo?',follow:[{label:'Definir roles para todos',user:'Me ayudaría definir roles dentro del equipo.',gabi:'Puedes alternar quién coordina, registra, presenta y verifica que todos hayan aportado. Cambia los roles en cada actividad.',take:'Las sugerencias son puntos de partida para diseñar una mejor experiencia de aula.'},{label:'Revisar que todos participen',user:'Quiero saber si cada integrante aportó.',gabi:'Pide al finalizar una breve reflexión individual: qué aporté, qué aprendí y qué apoyo necesité. Contrasta esas respuestas con tu observación.',take:'El criterio profesional sigue en manos del docente.'}]},{label:'Resolver una discusión durante la clase',user:'Hola, Profe Gabi. Dos estudiantes discutieron en medio de la clase. Quiero responder sin empeorar el conflicto.',gabi:'Puedes separar la situación inmediata de la conversación posterior: primero recuperar la calma y la seguridad, luego escuchar a los involucrados según los protocolos de tu establecimiento. ¿Qué necesitas?',follow:[{label:'Bajar la tensión del momento',user:'Necesito una forma de bajar la tensión en ese momento.',gabi:'Habla con un tono tranquilo, evita exponer a los estudiantes frente al grupo y solicita apoyo del equipo escolar si la situación lo requiere.',take:'En conflictos complejos, la herramienta no reemplaza los protocolos ni el apoyo humano.'},{label:'Conversar después del incidente',user:'Me gustaría saber cómo conversar después.',gabi:'Puedes preguntar qué ocurrió, cómo se sintieron y qué acciones ayudarían a reparar la situación, siguiendo las orientaciones de tu escuela.',take:'El acompañamiento humano y los protocolos escolares siguen siendo fundamentales.'}]}]},
{icon:'♡',title:'Cuidar mi bienestar',sub:'Organización y autocuidado',lead:'Sientes que el trabajo docente se acumula cada semana.',question:'¿Sobre qué quisieras conversar?',options:[{label:'No alcanzo a preparar todo',user:'Hola, Profe Gabi. Soy docente principiante y siento que no me alcanza el tiempo para planear mis clases.',gabi:'Eso puede pasar al comenzar. Podrías ordenar las tareas según lo urgente y lo importante, y reutilizar estructuras de planificación. ¿Qué quieres organizar primero?',follow:[{label:'Priorizar mis tareas',user:'Quiero aprender a priorizar lo que debo hacer.',gabi:'Anota lo que debes resolver mañana, lo que puedes planificar esta semana y lo que conviene conversar con tu equipo. Empieza por una tarea importante y abordable.',take:'Profe Gabi puede acompañar la organización del trabajo, no asumir todas las responsabilidades.'},{label:'Simplificar la planificación',user:'Necesito planificar sin empezar siempre desde cero.',gabi:'Puedes crear una plantilla sencilla con objetivo, actividad inicial, práctica y cierre. Adáptala a cada grupo y revisa con colegas qué materiales ya existen.',take:'La orientación ayuda a encontrar pasos viables y a buscar apoyo del equipo escolar.'}]},{label:'Me llevo trabajo a casa',user:'Hola, Profe Gabi. Me estoy llevando muchas tareas del colegio a casa y quiero organizarme mejor.',gabi:'Podemos pensar estrategias pequeñas y realistas. ¿Prefieres revisar tu horario o buscar apoyo para distribuir tareas?',follow:[{label:'Organizar mejor mi horario',user:'Me gustaría revisar cómo distribuyo el tiempo.',gabi:'Prueba reservar bloques cortos para planificar y corregir, junto con pausas definidas. Revisa después qué fue realista mantener.',take:'El bienestar docente también depende de las condiciones de trabajo y del apoyo institucional.'},{label:'Pedir apoyo a mi equipo',user:'Quiero conversar con colegas para no hacerlo todo solo.',gabi:'Podrías explicar qué tareas te están tomando más tiempo y preguntar por materiales compartidos o criterios de priorización. No necesitas resolverlo todo de manera individual.',take:'La herramienta complementa, pero no sustituye, una red humana de apoyo.'}]},{label:'Me siento inseguro al comenzar',user:'Hola, Profe Gabi. Estoy empezando a enseñar y a veces dudo mucho de mis decisiones.',gabi:'Aprender a enseñar toma tiempo. Puede ayudarte identificar una situación concreta, reconocer qué sí funcionó y conversar con un mentor sobre lo que mejorarías. ¿Qué te sería más útil?',follow:[{label:'Reflexionar después de una clase',user:'Quiero aprender a reflexionar sobre cómo salió mi clase.',gabi:'Puedes anotar tres cosas: qué buscabas lograr, qué observaste y qué cambiarías. Elige solo un ajuste para la próxima vez.',take:'El acompañamiento combina reflexión profesional con apoyo humano.'},{label:'Preparar una conversación con mi mentor',user:'Quiero saber cómo pedir orientación a mi mentor.',gabi:'Lleva un ejemplo específico de tu clase, explica qué intentaste y formula una pregunta concreta. Así la conversación puede enfocarse en posibilidades de mejora.',take:'Profe Gabi busca complementar la mentoría, no reemplazarla.'}]}]}
];
const control=document.getElementById('control'),messages=document.getElementById('messages'),hint=document.getElementById('hint');let state={topic:null,branch:null,stage:0};let pending=[];let run=0;
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function setControl(title,subtitle,opts,handler){control.innerHTML=`<h2>${escapeHtml(title)}</h2><p class="description">${escapeHtml(subtitle)}</p><div class="options">${opts.map((o,i)=>`<button class="option" data-index="${i}"><span class="bullet">${escapeHtml(o.icon||String.fromCharCode(65+i))}</span><span><strong>${escapeHtml(o.label)}</strong>${o.sub?`<small>${escapeHtml(o.sub)}</small>`:''}</span></button>`).join('')}</div><div class="toolbar"><span class="counter">${state.stage===0?'Selecciona un tema':state.stage===1?'Elige tu pregunta':'Continúa la conversación'}</span></div>`;control.querySelectorAll('.option').forEach(b=>b.addEventListener('click',()=>handler(Number(b.dataset.index))))}
function bubble(role,text){let el=document.createElement('div');el.className='message '+role;const label=document.createElement('span');label.className='who';label.textContent=role==='gabi'?'PROFE GABI':'TÚ';el.appendChild(label);el.appendChild(document.createTextNode(text));messages.appendChild(el);messages.scrollTop=messages.scrollHeight}
const compose=document.getElementById('compose'),draft=document.getElementById('draftText'),cursor=document.getElementById('cursor'),sendIcon=document.getElementById('sendIcon');
function lockChoices(){control.querySelectorAll('button.option').forEach(b=>b.disabled=true)}
function scrollChat(){messages.scrollTop=messages.scrollHeight}
function sleep(ms){return new Promise(r=>{const t=setTimeout(r,ms);pending.push(t)})}
function resetCompose(){draft.textContent='';cursor.style.display='none';compose.classList.remove('writing');sendIcon.classList.remove('busy')}
async function sendSimulated(text,after){
 const id=run;lockChoices();resetCompose();compose.classList.add('writing');cursor.style.display='inline-block';sendIcon.classList.add('busy');
 // Teclado humano simulado: se escribe literalmente en el campo, antes de enviar.
 for(let i=0;i<text.length;i++){
   if(id!==run)return;
   draft.textContent+=text[i];
   const c=text[i],delay=c===' '?55:'.!?'.includes(c)?210:',;'.includes(c)?135:55;
   await sleep(delay);
 }
 if(id!==run)return;
 await sleep(480);if(id!==run)return;
 resetCompose();bubble('user',text);if(after)after();
}
async function reply(text,after){
 const id=run;let el=document.createElement('div');el.className='typing thinking';
 el.innerHTML='<span aria-hidden="true">✦</span><span>Profe Gabi está pensando</span><span class="thinking-dots" aria-hidden="true">•••</span>';
 messages.appendChild(el);scrollChat();
 const thinkingTime=Math.min(3000,Math.max(1700,900+text.length*8));
 await sleep(thinkingTime);if(id!==run)return;
 el.remove();bubble('gabi',text);if(after)after();
}
function fresh(){run++;pending.forEach(clearTimeout);pending=[];resetCompose();messages.innerHTML='';state={topic:null,branch:null,stage:0};bubble('gabi','¡Hola! Soy Profe Gabi. ¿En qué te gustaría recibir orientación hoy?');hint.textContent='Selecciona uno de los tres temas. Las preguntas y respuestas aparecerán como mensajes naturales en la pantalla.';setControl('Imagina que hoy eres docente…','¿Qué situación te gustaría resolver con Profe Gabi?',conversations.map(x=>({icon:x.icon,label:x.title,sub:x.sub})),chooseTopic)}
function chooseTopic(index){run++;state={topic:index,branch:null,stage:1};let t=conversations[index];hint.textContent='Ahora elige la consulta que se enviará como si la hubieras escrito por WhatsApp.';control.innerHTML='<h2>Profe Gabi está preparando una pregunta…</h2><p class="description">La conversación se mostrará en la pantalla.</p>';sendSimulated('Quisiera orientación sobre '+t.title.toLowerCase()+'.',()=>reply('¡Claro! '+t.question,()=>{setControl(t.question,t.lead,t.options.map(x=>({label:x.label})),chooseBranch)}))}
function chooseBranch(index){run++;state.branch=index;state.stage=2;let t=conversations[state.topic],b=t.options[index];hint.textContent='Observa la respuesta de Profe Gabi y selecciona cómo quieres continuar la conversación.';control.innerHTML='<h2>Profe Gabi está respondiendo…</h2><p class="description">Tu mensaje se escribe letra por letra y luego Profe Gabi piensa antes de responder.</p>';sendSimulated(b.user,()=>reply(b.gabi,()=>{setControl('¿Qué le contestarías ahora?','Elige cómo continuar. Cada opción se convertirá en un mensaje redactado naturalmente.',b.follow.map(x=>({label:x.label})),chooseFollow)}))}
function chooseFollow(index){run++;let b=conversations[state.topic].options[state.branch],f=b.follow[index];state.stage=3;hint.textContent='La conversación concluye con un aprendizaje sobre el rol de esta herramienta.';control.innerHTML='<h2>Profe Gabi está respondiendo…</h2><p class="description">La conversación terminará después de esta orientación.</p>';sendSimulated(f.user,()=>reply(f.gabi,()=>{reply('Recuerda: estas ideas son puntos de partida. Tu criterio profesional y el acompañamiento de mentores y colegas siguen siendo esenciales.',()=>finish(f.take))}))}
function finish(take){state.stage=4;control.innerHTML=`<h2>¡Conversación completada!</h2><p class="description">Acabas de explorar un ejemplo de cómo Profe Gabi podría acompañar a un docente principiante.</p><div class="end-card"><b>¿Qué aprendiste?</b>${escapeHtml(take)}<br><br>Este recorrido se hizo con respuestas predefinidas, sin procesar lenguaje natural ni conectarse a una IA real.</div><div class="toolbar"><button class="primary" id="again">Probar otro tema ↗</button><button class="secondary" id="same">Ver otra conversación</button></div>`;document.getElementById('again').onclick=fresh;document.getElementById('same').onclick=()=>chooseTopic(state.topic);hint.textContent='En una exposición, esta pantalla puede proyectarse en el televisor mientras las decisiones se hacen desde la tableta.'}
document.getElementById('reset').addEventListener('click',fresh);fresh();
